select * from ( select * from ( SELECT P1.PROPERNAME reportType1, P2.PROPERNAME reportType2, P3.PROPERNAME reportType3, P4.PROPERNAME reportType4, P5.PROPERNAME reportType5, P6.PROPERNAME reportType6, P.DETAILNO,P.DETAILNO2, P.PRODID, PB.PROD_NAME prodName, PB.IS_FHXGCP isFhxgcp, CASE WHEN EX.SRCFIELD1 IS NOT NULL AND EX.SRCFIELD1 != '3003' THEN NULL else P.ASSET_CODE end assetCode, CASE WHEN EX.SRCFIELD1 IS NOT NULL AND EX.SRCFIELD1 != '3003' THEN '现金' ELSE IFNULL(B.SUBJECT_NAME,I.ASSET_NAME) END assetName, I.VDATE, I.MDATE, /**企业债,取资产基本信息(2-5逻辑)其余取贷款的信息(2-2~2-4逻辑)**/ P.party_Type1 partyType1, IFNULL(MC.CUSTOMER_NAME, IFNULL(mp1.COUNTER_NAME,P.SUBJECT_NAME)) subjectName, P.INDUSTRY INDUSTRY, P.borrower_city buyPlace, IFNULL(I.ASSET_YIELD,RATE.ASSET_RATE) RATE, P.CCY, AP.POS_AMT delayPayAmt, AP.TDY_COST_AMT costAmt, AP.TDY_FLOAT_INGPL floatIngpl, AP.TDY_INTINCEXP INTINCEXP, AP.TDY_INTADJEXP_ADD intadjexpAdd, AP.TDY_LOSS_AMT lossAmt, P.AMT, IFNULL(mp.COUNTER_NAME,p.RIVAL_PARTY) rivalParty, I.ORG_ASSET_TYPE1 orgAssetType1, I.ORG_ASSET_TYPE2 orgAssetType2, I.ORG_ASSET_TYPE3 orgAssetType3, P.END_DAYS endDays, CASE WHEN AP.MDATE != I.MDATE and I.MDATE is not null THEN AP.MDATE END openplan /*CASE WHEN i.option_flag = '01' and AP.MDATE!=I.MDATE THEN AP.MDATE END openplan*/ FROM PBC_MONTH_ASSET_POSITIONDETAIL P LEFT JOIN PBC_REPORT_TEMPLATE T ON T.PROPERTYCODE = P.DETAILNO AND T.REPORTTYPE != 'ONEPRD_ASSET_DEBT' LEFT JOIN PBC_REPORT_TEMPLATE T1 ON T1.PROPERTYCODE = P.DETAILNO2 AND T1.REPORTTYPE != 'ONEPRD_ASSET_DEBT' LEFT JOIN CHB_PRD_BASEINFO PB ON P.PRODID=PB.PROD_ID AND PB.FPROD_ID IS NULL AND PB.STATUS IN ('E','M') LEFT JOIN CHB_ASSET_INFO I ON I.ASSET_CODE = P.ASSET_CODE LEFT JOIN BOK_SUBJECT B ON B.BOOKSET_ID = '00000000000000000002' AND B.SUBJECT_NO = P.ASSET_CODE LEFT JOIN MST_CUSTOMER_INFO MC ON MC.CUSTOMER_ID = P.SUBJECT_NAME LEFT JOIN CHB_MST_COUNTER_PARTY MP1 ON MP1.COUNTER_ID = P.SUBJECT_NAME LEFT JOIN CHB_MST_COUNTER_PARTY MP ON MP.COUNTER_ID = P.RIVAL_PARTY /*LEFT JOIN CHB_ASSETS_BASIS_DATA AP ON AP.PROD_ID = P.PRODID AND AP.ASSET_ID = P.ASSET_CODE AND AP.VALUE_DATE = DECODE(P.TERM,NULL,TO_DATE('19000101','yyyyMMdd'),ADD_MONTHS(TO_DATE(P.TERM||'01','yyyyMMdd'),1)-1)*/ LEFT JOIN CHB_ASSETS_BASIS_DATA AP ON AP.PROD_ID = P.PRODID AND AP.ASSET_ID = P.ASSET_CODE AND AP.VALUE_DATE = (case P.TERM when NULL then STR_TO_DATE('19000101','%Y%m%d') else adddate(STR_TO_DATE(concat(P.TERM,'01'),'%Y%m%d'),interval 1 month)-1 end) LEFT JOIN PBC_REPORT_TEMPLATEDETAIL P6 ON P6.PROPERTYCODE = P.DETAILNO AND P6.PROPLEVEL = '6' AND P6.STATUS='E' LEFT JOIN PBC_REPORT_TEMPLATEDETAIL P5 ON (P5.PROPERTYCODE = P6.CODEPARENT or (p.detailno2 is not null and p5.propertycode = p.detailno2)) AND P5.PROPLEVEL = '5' AND P5.STATUS='E' LEFT JOIN PBC_REPORT_TEMPLATEDETAIL P4 ON P4.PROPERTYCODE = P5.CODEPARENT AND P4.PROPLEVEL = '4' AND P4.STATUS='E' LEFT JOIN PBC_REPORT_TEMPLATEDETAIL P3 ON P3.PROPERTYCODE = P4.CODEPARENT AND P3.PROPLEVEL = '3' AND P3.STATUS='E' LEFT JOIN PBC_REPORT_TEMPLATEDETAIL P2 ON P2.PROPERTYCODE = P3.CODEPARENT AND P2.PROPLEVEL = '2' AND P2.STATUS='E' LEFT JOIN PBC_REPORT_TEMPLATEDETAIL P1 ON P1.PROPERTYCODE = P2.CODEPARENT AND P1.PROPLEVEL = '1' AND P1.STATUS='E' LEFT JOIN CHB_TYPE_MAPPING_EX EX ON EX.SRCFIELD1 = P.ASSET_CODE AND EX.MAPPINGCODE = 'MAPPINGCODE_SUBJECTNO' AND EX.OBJFIELD3 = 'C01' LEFT JOIN (SELECT ASSET_ID,ifnull(ASSET_RATE,0) * 100 ASSET_RATE,CHANGE_DATE, ROW_NUMBER() OVER (PARTITION BY ASSET_ID ORDER BY CHANGE_DATE DESC ) monthMarkNo FROM CHB_ASSET_RATE WHERE ASSET_RATE is not null AND CHANGE_DATE <= #{enddateDate,jdbcType=DATE}) RATE ON RATE.ASSET_ID = P.ASSET_CODE AND RATE.monthMarkNo = 1
WHERE P.AMT IS NOT NULL AND P.AMT !=0
and P.TERM = #{enddate,jdbcType=VARCHAR}
